import sys
from collections import deque

# ------------------------------------------------------------
# Dinic max flow implementation
# ------------------------------------------------------------
class FlowEdge:
    def __init__(self, v, u, cap):
        self.v = v
        self.u = u
        self.cap = cap
        self.flow = 0

class Dinic:
    def __init__(self, n, s, t):
        self.n = n
        self.s = s
        self.t = t
        self.edges = []
        self.adj = [[] for _ in range(n)]
        self.level = [0] * n
        self.ptr = [0] * n
        self.m = 0

    def add_edge(self, v, u, cap):
        self.edges.append(FlowEdge(v, u, cap))
        self.edges.append(FlowEdge(u, v, 0))
        self.adj[v].append(self.m)
        self.adj[u].append(self.m + 1)
        self.m += 2

    def bfs(self):
        q = deque()
        self.level = [-1] * self.n
        self.level[self.s] = 0
        q.append(self.s)
        while q:
            v = q.popleft()
            for id_ in self.adj[v]:
                if self.edges[id_].cap - self.edges[id_].flow < 1:
                    continue
                if self.level[self.edges[id_].u] != -1:
                    continue
                self.level[self.edges[id_].u] = self.level[v] + 1
                q.append(self.edges[id_].u)
        return self.level[self.t] != -1

    def dfs(self, v, pushed):
        if pushed == 0:
            return 0
        if v == self.t:
            return pushed
        for i in range(self.ptr[v], len(self.adj[v])):
            self.ptr[v] = i
            id_ = self.adj[v][i]
            u = self.edges[id_].u
            if self.level[v] + 1 != self.level[u] or self.edges[id_].cap - self.edges[id_].flow < 1:
                continue
            tr = self.dfs(u, min(pushed, self.edges[id_].cap - self.edges[id_].flow))
            if tr == 0:
                continue
            self.edges[id_].flow += tr
            self.edges[id_ ^ 1].flow -= tr
            return tr
        return 0

    def flow(self):
        flow = 0
        INF = 10**18
        while True:
            if not self.bfs():
                break
            self.ptr = [0] * self.n
            while True:
                pushed = self.dfs(self.s, INF)
                if pushed == 0:
                    break
                flow += pushed
        return flow

# ------------------------------------------------------------
# Main program
# ------------------------------------------------------------
def main():
    sys.setrecursionlimit(10000)

    data = sys.stdin.read().splitlines()
    if not data:
        return
    first = data[0].split()
    n = int(first[0])
    t = int(first[1])

    sci = []
    cap = []
    for i in range(1, n+1):
        sci.append(data[i].strip())
    for i in range(n+1, 2*n+1):
        cap.append(data[i].strip())

    # 4-direction offsets
    dx = [1, -1, 0, 0]
    dy = [0, 0, 1, -1]

    # BFS to compute distances from the first 'Z'
    dis = None
    for i in range(n):
        for j in range(n):
            if sci[i][j] == 'Z':
                # BFS from (i,j)
                dis = [[-1]*n for _ in range(n)]
                q = deque()
                q.append((i, j))
                dis[i][j] = 0
                while q:
                    x, y = q.popleft()
                    for d in range(4):
                        nx = x + dx[d]
                        ny = y + dy[d]
                        if 0 <= nx < n and 0 <= ny < n:
                            if sci[nx][ny] != 'Y' and sci[nx][ny] != 'Z':
                                if dis[nx][ny] == -1:
                                    dis[nx][ny] = dis[x][y] + 1
                                    q.append((nx, ny))
                # set unreachable cells to a large number
                for a in range(n):
                    for b in range(n):
                        if dis[a][b] == -1:
                            dis[a][b] = 1000000000
                break
        if dis is not None:
            break

    # DP memoization: dp[tt][x0][y0][x][y]
    # dimensions: t+1, n, n, n, n
    dp = [[[[[-1 for _ in range(n)] for _ in range(n)] for _ in range(n)] for _ in range(n)] for _ in range(t+1)]

    # recursive function that determines if scientist at (x0,y0) can reach capsule at (x,y)
    # at time tt (0-indexed)
    def pos(tt, x0, y0, x, y):
        if dis[x0][y0] < tt:
            return 0
        if x0 == x and y0 == y:
            return 1
        if tt >= t:
            return 0
        if dis[x0][y0] <= tt:
            return 0
        if dp[tt][x0][y0][x][y] != -1:
            return dp[tt][x0][y0][x][y]
        for d in range(4):
            xx = x0 + dx[d]
            yy = y0 + dy[d]
            if xx < 0 or xx >= n or yy < 0 or yy >= n:
                continue
            if sci[xx][yy] == 'Y' or sci[xx][yy] == 'Z':
                continue
            if pos(tt+1, xx, yy, x, y):
                dp[tt][x0][y0][x][y] = 1
                return 1
        dp[tt][x0][y0][x][y] = 0
        return 0

    # collect scientist and capsule positions
    sc = []
    cp = []
    for i in range(n):
        for j in range(n):
            if sci[i][j] not in ('0', 'Y', 'Z'):
                sc.append((i, j))
    for i in range(n):
        for j in range(n):
            if cap[i][j] not in ('0', 'Y', 'Z'):
                cp.append((i, j))

    # build flow network
    sz_sc = len(sc)
    sz_cp = len(cp)
    sink = sz_sc + sz_cp + 1
    dinic = Dinic(sink+1, 0, sink)

    # source -> scientists
    for i, (x, y) in enumerate(sc):
        c = ord(sci[x][y]) - ord('0')
        dinic.add_edge(0, i+1, c)

    # capsules -> sink
    for i, (x, y) in enumerate(cp):
        c = ord(cap[x][y]) - ord('0')
        dinic.add_edge(sz_sc + 1 + i, sink, c)

    # edges between scientists and capsules if reachable
    for i, (sx, sy) in enumerate(sc):
        for j, (cx, cy) in enumerate(cp):
            if pos(0, sx, sy, cx, cy):
                dinic.add_edge(i+1, sz_sc + 1 + j, 10000000)

    print(dinic.flow())

if __name__ == "__main__":
    main()
